#!/usr/bin/env bash
# Runs INSIDE termux/termux-docker:aarch64 on a GitHub ARM64 runner: a real Android
# Bionic userland (bionic libc + /system/bin/linker64) on ARM64 hardware.
#
# It installs the Python Eye PRoot bundle OUTSIDE the Termux prefix (exactly like the
# IDE does in its own app storage), unpacks the rootfs that the IDE's Kotlin
# RootfsExtractor produced, boots Ubuntu with the PRoot arguments generated by the
# IDE's ProotCommand, then installs + probes every recipe of linux-packages.json.
#
# usage: termux_verify.sh <dist dir> <results dir>
set -uo pipefail
DIST="$1"
OUT="$2"
BASE="/data/data/com.termux/files/home/python-eye-linux"   # must match the harness 'command' base
LOGS="$OUT/logs"
RESULTS="$OUT/results.tsv"
mkdir -p "$BASE/tmp" "$BASE/projects-host/demo" "$LOGS"
: > "$RESULTS"
log() { echo "[pyeye-ci] $*"; }

log "kernel: $(uname -a)"
log "user: $(id)"
log "linker64: $(ls -l /system/bin/linker64 2>&1)"
log "Termux libtalloc present? $(ls "${PREFIX:-/data/data/com.termux/files/usr}"/lib/libtalloc* 2>/dev/null || echo no)"

tar -xzf "$DIST"/proot-android-arm64-*.tar.gz -C "$BASE" || { log "bundle unpack failed"; exit 1; }
mkdir -p "$BASE/ubuntu"
tar -xpf "$DIST/rootfs-prepared.tar" -C "$BASE/ubuntu" 2> "$LOGS/rootfs-untar.txt" || { log "rootfs untar failed"; tail -20 "$LOGS/rootfs-untar.txt"; exit 1; }
cp -r "$DIST/proc-fake" "$BASE/proc-fake"

mapfile -t ARGS < "$DIST/proot-args.txt"
mapfile -t ENVS < "$DIST/proot-env.txt"
if [ -f "$BASE/proot/libexec/proot/loader32" ]; then ENVS+=("PROOT_LOADER_32=$BASE/proot/libexec/proot/loader32"); fi
log "proot env: ${ENVS[*]}"

# guest <timeout seconds> <bash command>
guest() {
  local t="$1"
  local a=("${ARGS[@]}")
  a[${#a[@]}-1]="$2"
  timeout --kill-after=30 "$t" env "${ENVS[@]}" "${a[@]}"
}
b64() { printf '%s' "$1" | base64 | tr -d '\n'; }

env "${ENVS[@]}" "$BASE/proot/bin/proot" --version > "$OUT/proot-version.txt" 2>&1
log "proot --version exit=$? : $(head -n3 "$OUT/proot-version.txt" | tr '\n' ' ')"

guest 300 'cat /etc/os-release; echo "arch=$(uname -m)"; id; echo pyeye-boot-ok' > "$OUT/boot.txt" 2>&1
if ! grep -q pyeye-boot-ok "$OUT/boot.txt"; then
  log "BOOT FAILED"; cat "$OUT/boot.txt"; exit 1
fi
log "boot OK: $(grep PRETTY_NAME "$OUT/boot.txt")"

guest 120 'cd /root/projects/demo && echo hello-from-ubuntu > ci.txt && pwd' > "$OUT/bind.txt" 2>&1
if [ "$(cat "$BASE/projects-host/demo/ci.txt" 2>/dev/null)" = "hello-from-ubuntu" ]; then
  log "project folder bind OK"; echo ok > "$OUT/bind-status.txt"
else
  log "project folder bind FAILED"; cat "$OUT/bind.txt"; echo failed > "$OUT/bind-status.txt"
fi

if ! guest 1200 'apt-get update' > "$OUT/apt-update.txt" 2>&1; then
  log "apt-get update FAILED"; tail -40 "$OUT/apt-update.txt"; exit 1
fi
log "apt-get update OK"

declare -A STATUS
while IFS=$'\t' read -r id needs timeout inst probe expect; do
  [ -z "${id:-}" ] && continue
  missing=""
  if [ "$needs" != "-" ]; then
    IFS=',' read -ra NS <<< "$needs"
    for n in "${NS[@]}"; do [ "${STATUS[$n]:-}" = "ok" ] || missing="$n"; done
  fi
  if [ -n "$missing" ]; then
    STATUS[$id]="skipped"
    printf '%s\tskipped\t0\t%s\n' "$id" "$(b64 "needs $missing, which did not pass")" >> "$RESULTS"
    log "$id: SKIPPED (needs $missing)"
    continue
  fi
  icmd=$(printf '%s' "$inst" | base64 -d)
  pcmd=$(printf '%s' "$probe" | base64 -d)
  ere=$(printf '%s' "$expect" | base64 -d | sed 's/\\d/[0-9]/g')
  t0=$(date +%s)
  guest "$timeout" "$icmd" > "$LOGS/$id.install.txt" 2>&1
  irc=$?
  guest 300 "$pcmd" > "$LOGS/$id.probe.txt" 2>&1
  prc=$?
  secs=$(( $(date +%s) - t0 ))
  if [ $irc -eq 0 ] && [ $prc -eq 0 ] && grep -Eq -- "$ere" "$LOGS/$id.probe.txt"; then
    STATUS[$id]="ok"
  elif [ $irc -eq 124 ] || [ $irc -eq 137 ]; then
    STATUS[$id]="timeout"
  elif [ $irc -ne 0 ]; then
    STATUS[$id]="install_failed"
  else
    STATUS[$id]="probe_failed"
  fi
  if [ "${STATUS[$id]}" = "ok" ]; then detail=$(tail -c 600 "$LOGS/$id.probe.txt"); else detail=$(tail -c 1500 "$LOGS/$id.install.txt"; echo; echo "--- probe ---"; tail -c 600 "$LOGS/$id.probe.txt"); fi
  printf '%s\t%s\t%s\t%s\n' "$id" "${STATUS[$id]}" "$secs" "$(b64 "$detail")" >> "$RESULTS"
  log "$id: ${STATUS[$id]} (${secs}s) install=$irc probe=$prc"
done < "$DIST/recipes.tsv"

guest 300 'du -sh / --exclude=/proc --exclude=/sys --exclude=/dev 2>/dev/null | tail -n1' > "$OUT/disk.txt" 2>&1
log "disk: $(cat "$OUT/disk.txt")"
log "done: $(grep -c $'\tok\t' "$RESULTS") ok of $(wc -l < "$RESULTS")"
exit 0
